/** Lifting area a weight W (N) needs at airspeed v (m/s): S >= 2 W / (rho v^2 CLmax). Theorem Delphi.vmin_le, rearranged. */
export function liftingAreaNeeded(W_N, v, rho, CLmax) { return 2 * W_N / (rho * v * v * CLmax); }
